-- Migration 002: expanded domain contracts; run after 001_core.sql (PostgreSQL 16+)
BEGIN;
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, display_name text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE teams (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text UNIQUE NOT NULL, name text NOT NULL);
CREATE TABLE team_members (team_id uuid NOT NULL REFERENCES teams(id), user_id uuid NOT NULL REFERENCES users(id), PRIMARY KEY(team_id,user_id));
CREATE TABLE roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, description text NOT NULL);
CREATE TABLE permissions (code text PRIMARY KEY, description text NOT NULL);
CREATE TABLE role_permissions (role_id uuid NOT NULL REFERENCES roles(id), permission_code text NOT NULL REFERENCES permissions(code), PRIMARY KEY(role_id,permission_code));
CREATE TABLE access_grants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), role_id uuid NOT NULL REFERENCES roles(id), scope_type text NOT NULL CHECK(scope_type IN ('global','customer','site','project','team')), scope_id uuid, valid_from timestamptz NOT NULL DEFAULT now(), valid_to timestamptz, CHECK ((scope_type='global' AND scope_id IS NULL) OR (scope_type<>'global' AND scope_id IS NOT NULL)), CHECK(valid_to IS NULL OR valid_to>valid_from));
CREATE INDEX idx_grants_user_scope ON access_grants(user_id,scope_type,scope_id);
CREATE TABLE contacts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES customers(id), full_name text NOT NULL, email text, phone text, active boolean NOT NULL DEFAULT true);
CREATE TABLE contracts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES customers(id), contract_no text NOT NULL UNIQUE, starts_at timestamptz NOT NULL, ends_at timestamptz, status text NOT NULL CHECK(status IN ('draft','active','expired','terminated')), CHECK(ends_at IS NULL OR ends_at>starts_at), UNIQUE(id,customer_id));
CREATE TABLE contract_coverage (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), contract_id uuid NOT NULL, customer_id uuid NOT NULL, site_id uuid, service_id uuid, asset_id uuid, valid_from timestamptz NOT NULL, valid_to timestamptz, CHECK(num_nonnulls(site_id,service_id,asset_id)=1), CHECK(valid_to IS NULL OR valid_to>valid_from), FOREIGN KEY(contract_id,customer_id) REFERENCES contracts(id,customer_id), FOREIGN KEY(site_id,customer_id) REFERENCES sites(id,customer_id), FOREIGN KEY(asset_id,customer_id) REFERENCES assets(id,customer_id));
ALTER TABLE services ADD CONSTRAINT uq_service_customer UNIQUE(id,customer_id);
ALTER TABLE contract_coverage ADD CONSTRAINT fk_coverage_service FOREIGN KEY(service_id,customer_id) REFERENCES services(id,customer_id);
CREATE TABLE sla_policies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), contract_id uuid NOT NULL REFERENCES contracts(id), ticket_type text NOT NULL CHECK(ticket_type IN ('incident','service_request')), priority text NOT NULL CHECK(priority IN ('p1','p2','p3','p4')), response_minutes int NOT NULL CHECK(response_minutes>0), restore_minutes int CHECK(restore_minutes>0), calendar_code text NOT NULL, active boolean NOT NULL DEFAULT true, UNIQUE(contract_id,ticket_type,priority));
CREATE TABLE project_tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id), parent_id uuid REFERENCES project_tasks(id), title text NOT NULL, status text NOT NULL DEFAULT 'todo' CHECK(status IN ('todo','in_progress','blocked','review','done','cancelled')), weight numeric(10,3) NOT NULL DEFAULT 1 CHECK(weight>0), progress numeric(5,2) NOT NULL DEFAULT 0 CHECK(progress BETWEEN 0 AND 100), assigned_to uuid REFERENCES users(id), due_at timestamptz, version int NOT NULL DEFAULT 1 CHECK(version>0));
CREATE TABLE milestones (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id), title text NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','submitted','accepted','rework_required','waived')), mandatory boolean NOT NULL DEFAULT true, due_at timestamptz);
CREATE TABLE acceptance_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), milestone_id uuid NOT NULL REFERENCES milestones(id), site_id uuid NOT NULL REFERENCES sites(id), review_attempt int NOT NULL CHECK(review_attempt>0), decision text NOT NULL CHECK(decision IN ('submitted','accepted','rejected','waived')), reviewer_id uuid REFERENCES users(id), reason text, decided_at timestamptz, UNIQUE(milestone_id,site_id,review_attempt), CHECK(decision NOT IN ('rejected','waived') OR length(trim(coalesce(reason,'')))>0));
CREATE TABLE documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES customers(id), project_id uuid REFERENCES projects(id), site_id uuid REFERENCES sites(id), kind text NOT NULL, title text NOT NULL, classification text NOT NULL DEFAULT 'internal' CHECK(classification IN ('public','customer','internal','restricted')));
CREATE TABLE document_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), document_id uuid NOT NULL REFERENCES documents(id), revision int NOT NULL CHECK(revision>0), object_key text NOT NULL UNIQUE, sha256 text NOT NULL CHECK(length(sha256)=64), status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','submitted','approved','rejected','superseded')), uploaded_by uuid NOT NULL REFERENCES users(id), uploaded_at timestamptz NOT NULL DEFAULT now(), UNIQUE(document_id,revision));
CREATE TABLE approval_decisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), document_version_id uuid REFERENCES document_versions(id), acceptance_id uuid REFERENCES acceptance_records(id), reviewer_id uuid NOT NULL REFERENCES users(id), decision text NOT NULL CHECK(decision IN ('approve','reject')), reason text, decided_at timestamptz NOT NULL DEFAULT now(), CHECK(num_nonnulls(document_version_id,acceptance_id)=1));
CREATE TABLE asset_installations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid NOT NULL REFERENCES assets(id), task_id uuid REFERENCES project_tasks(id), site_id uuid NOT NULL REFERENCES sites(id), installed_by uuid NOT NULL REFERENCES users(id), installed_at timestamptz NOT NULL DEFAULT now(), evidence_version_id uuid REFERENCES document_versions(id));
CREATE TABLE ticket_assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ticket_id uuid NOT NULL REFERENCES tickets(id), assignee_id uuid NOT NULL REFERENCES users(id), assigned_by uuid NOT NULL REFERENCES users(id), assigned_at timestamptz NOT NULL DEFAULT now(), released_at timestamptz, CHECK(released_at IS NULL OR released_at>=assigned_at));
CREATE UNIQUE INDEX one_active_ticket_assignment ON ticket_assignments(ticket_id) WHERE released_at IS NULL;
CREATE TABLE ticket_sla (ticket_id uuid PRIMARY KEY REFERENCES tickets(id), policy_id uuid REFERENCES sla_policies(id), state text NOT NULL CHECK(state IN ('policy_missing','running','paused','met','breached')), response_due_at timestamptz, restore_due_at timestamptz, CHECK((state='policy_missing' AND policy_id IS NULL AND response_due_at IS NULL AND restore_due_at IS NULL) OR state<>'policy_missing'));
CREATE TABLE ticket_links (ticket_id uuid NOT NULL REFERENCES tickets(id), asset_id uuid REFERENCES assets(id), ci_id uuid REFERENCES configuration_items(id), service_id uuid REFERENCES services(id), CHECK(num_nonnulls(asset_id,ci_id,service_id)=1));
CREATE UNIQUE INDEX ticket_asset_link_unique ON ticket_links(ticket_id,asset_id) WHERE asset_id IS NOT NULL;
CREATE UNIQUE INDEX ticket_ci_link_unique ON ticket_links(ticket_id,ci_id) WHERE ci_id IS NOT NULL;
CREATE UNIQUE INDEX ticket_service_link_unique ON ticket_links(ticket_id,service_id) WHERE service_id IS NOT NULL;
CREATE TABLE maintenance_plans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES customers(id), site_id uuid NOT NULL, title text NOT NULL, recurrence_rule text NOT NULL, timezone text NOT NULL, active boolean NOT NULL DEFAULT true, FOREIGN KEY(site_id,customer_id) REFERENCES sites(id,customer_id));
CREATE TABLE checklist_templates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, title text NOT NULL, revision int NOT NULL CHECK(revision>0));
CREATE TABLE checklist_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), template_id uuid NOT NULL REFERENCES checklist_templates(id), ordinal int NOT NULL CHECK(ordinal>0), prompt text NOT NULL, required boolean NOT NULL DEFAULT true, evidence_required boolean NOT NULL DEFAULT false, UNIQUE(template_id,ordinal));
CREATE TABLE work_orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), plan_id uuid REFERENCES maintenance_plans(id), ticket_id uuid REFERENCES tickets(id), site_id uuid NOT NULL REFERENCES sites(id), template_id uuid REFERENCES checklist_templates(id), assigned_to uuid REFERENCES users(id), status text NOT NULL DEFAULT 'planned' CHECK(status IN ('planned','assigned','in_progress','review','completed','cancelled')), scheduled_at timestamptz, completed_at timestamptz, version int NOT NULL DEFAULT 1 CHECK(version>0));
CREATE TABLE checklist_answers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), work_order_id uuid NOT NULL REFERENCES work_orders(id), item_id uuid NOT NULL REFERENCES checklist_items(id), answer text NOT NULL, evidence_version_id uuid REFERENCES document_versions(id), answered_by uuid NOT NULL REFERENCES users(id), answered_at timestamptz NOT NULL DEFAULT now(), UNIQUE(work_order_id,item_id));
CREATE TABLE change_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES customers(id), site_id uuid REFERENCES sites(id), title text NOT NULL, risk text NOT NULL CHECK(risk IN ('low','medium','high','critical')), status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','assessing','pending_approval','approved','implementing','verified','closed','rejected')), rollback_plan text, requested_by uuid NOT NULL REFERENCES users(id));
CREATE TABLE audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid REFERENCES users(id), action text NOT NULL, resource_type text NOT NULL, resource_id uuid NOT NULL, customer_id uuid REFERENCES customers(id), old_values jsonb, new_values jsonb, occurred_at timestamptz NOT NULL DEFAULT now(), correlation_id uuid NOT NULL);
CREATE INDEX idx_audit_resource ON audit_events(resource_type,resource_id,occurred_at DESC);
CREATE TABLE notification_deliveries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), outbox_id uuid NOT NULL REFERENCES outbox_events(id), channel text NOT NULL CHECK(channel IN ('email','telegram','zalo','in_app')), recipient_ref text NOT NULL, status text NOT NULL CHECK(status IN ('pending','sent','failed','dead')), attempts int NOT NULL DEFAULT 0 CHECK(attempts>=0), last_attempt_at timestamptz, provider_message_id text, UNIQUE(outbox_id,channel,recipient_ref));
CREATE INDEX idx_tickets_customer_status ON tickets(customer_id,status,created_at DESC);
CREATE INDEX idx_placements_location ON asset_placements(location_id) WHERE valid_to IS NULL;
CREATE INDEX idx_workorders_schedule ON work_orders(status,scheduled_at);
COMMIT;
-- Application transactional invariants requiring service-level enforcement: cross-customer placement, approved version immutability, checklist completeness, transition guards, append-only audit.
-- Production gate: implement DB triggers/privileges and integration tests for these invariants before release.
